examples.nonCompliant:
function renderList(items) {
  return items.map(item => {
    const config = { theme: 'dark', padding: 10 }; // Non-compliant: allocated every iteration
    return transform(item, config);
  });
}

examples.compliant:
const DEFAULT_CONFIG = Object.freeze({ theme: 'dark', padding: 10 }); // Compliant: hoisted invariant
function renderList(items) {
  return items.map(item => transform(item, DEFAULT_CONFIG));
}

examples.nonCompliant:
function setupResize() {
  window.addEventListener('resize', handleResize); // Non-compliant: missing teardown
}

examples.compliant:
function setupResize() {
  window.addEventListener('resize', handleResize);
  return () => window.removeEventListener('resize', handleResize); // Compliant: disposal returned
}

examples.nonCompliant:
import HeavyChart from 'heavy-chart-library'; // Non-compliant: top-level static import
function showReport(shouldDisplay) {
  if (shouldDisplay) HeavyChart.render();
}

examples.compliant:
async function showReport(shouldDisplay) {
  if (shouldDisplay) {
    const { default: HeavyChart } = await import('heavy-chart-library'); // Compliant: lazy load
    HeavyChart.render();
  }
}

examples.nonCompliant:
function closeModal() {
  setIsModalOpen(false); // Non-compliant: modal closes without refocusing trigger element
}

examples.compliant:
function closeModal() {
  setIsModalOpen(false);
  triggerElementRef.current?.focus(); // Compliant: restores focus to trigger element
}
